        await waitFor(() => {
            expect(authProvider.getIdentity).toHaveBeenCalled();
        });
        queryClient.cancelQueries({
            queryKey: ['auth', 'getIdentity'],
        });
        await waitFor(() => {
            expect(abort).toHaveBeenCalled();
        });
    });
});

