                    }
                },

                onKeyDown(props) {
                    if (popup && popup[0] && props.event.key === 'Escape') {
                        popup[0].hide();

                        return true;
                    }

                    if (!component.ref) {
                        return false;
                    }

                    return component.ref.onKeyDown(props);
                },

                onExit() {
                    queueMicrotask(() => {
                        if (popup && popup[0] && !popup[0].state.isDestroyed) {
