                        value={{
                            ...defaultProps,
                            filterValues: { title: 'Lorem' },
                        }}
                    >
                        <Filter>
                            <TextInput source="title" />
                        </Filter>
                    </ListContext.Provider>
                </ResourceContextProvider>
            );

            expect(getByDisplayValue('Lorem')).not.toBeNull();
        });
    });
});

import * as React from 'react';
