 */
export const Filter = (props: FilterProps) => {
    const { children } = props;
    const renderButton = () => {
        return <FilterButton className={FilterClasses.button} />;
    };

    const renderForm = () => {
        return <FilterForm className={FilterClasses.form} />;
    };

    return (
        <FilterContext.Provider value={Children.toArray(children)}>
            {props.context === 'button' ? renderButton() : renderForm()}
        </FilterContext.Provider>
    );
};

Filter.propTypes = {
    children: PropTypes.node,
    classes: PropTypes.object,
    context: PropTypes.oneOf(['form', 'button']),
};

const PREFIX = 'RaFilter';

export const FilterClasses = {
    button: `${PREFIX}-button`,
    form: `${PREFIX}-form`,
};

export interface FilterProps {
    children: ReactNode;
    context?: 'form' | 'button';
    variant?: string;
}

import * as React from 'react';
import expect from 'expect';
import { render, fireEvent, screen, waitFor } from '@testing-library/react';
import { createTheme } from '@mui/material/styles';
import { ListContextProvider, ListControllerResult } from 'ra-core';

import { AdminContext } from '../../AdminContext';
import { FilterButton } from './FilterButton';
import { TextInput } from '../../input';
import { Basic, WithAutoCompleteArrayInput } from './FilterButton.stories';

const theme = createTheme();

describe('<FilterButton />', () => {
    const defaultListContext = ({
        resource: 'post',
        displayedFilters: {
            title: true,
            'customer.name': true,
        },
        showFilter: () => {},
        filterValues: {},
    } as unknown) as ListControllerResult;

    const defaultProps = {
        filters: [
            <TextInput source="title" label="Title" />,
            <TextInput source="customer.name" label="Name" />,
        ],
    };

    beforeAll(() => {
        window.scrollTo = jest.fn();
    });

    afterAll(() => {
        jest.clearAllMocks();
    });

    describe('filter selection menu', () => {
        it('should display only hidden filters', () => {
            const hiddenFilter = (
                <TextInput source="Returned" label="Returned" />
            );
            const { getByLabelText, queryByText } = render(
                <AdminContext theme={theme}>
                    <ListContextProvider value={defaultListContext}>
                        <FilterButton
                            {...defaultProps}
                            filters={defaultProps.filters.concat(hiddenFilter)}
                        />
                    </ListContextProvider>
                </AdminContext>
            );

            fireEvent.click(getByLabelText('ra.action.add_filter'));

            expect(queryByText('Returned')).not.toBeNull();
            expect(queryByText('Name')).toBeNull();
        });

        it('should display the filter button if all filters are shown and there is a filter value', () => {
            render(
                <AdminContext theme={theme}>
                    <ListContextProvider
                        value={{
                            ...defaultListContext,
                            displayedFilters: {
                                title: true,
                                'customer.name': true,
                            },
                            filterValues: { title: 'foo' },
                        }}
                    >
                        <FilterButton
                            filters={[
                                <TextInput source="title" label="Title" />,
                                <TextInput
                                    source="customer.name"
                                    label="Name"
                                />,
                            ]}
                        />
                    </ListContextProvider>
                </AdminContext>
            );
            expect(
                screen.queryByLabelText('ra.action.add_filter')
            ).not.toBeNull();
            fireEvent.click(screen.getByLabelText('ra.action.add_filter'));
            screen.getByText('ra.saved_queries.new_label');
        });

        it('should return disabled filter menu item when "disabled" passed to filter', () => {
            const hiddenFilter = (
                <TextInput source="Returned" label="Returned" disabled={true} />
            );
            const { getByLabelText, queryByText } = render(
                <AdminContext theme={theme}>
                    <ListContextProvider value={defaultListContext}>
                        <FilterButton
                            filters={defaultProps.filters.concat(hiddenFilter)}
                        />
                    </ListContextProvider>
                </AdminContext>
            );

            fireEvent.click(getByLabelText('ra.action.add_filter'));

            const disabledFilter = queryByText('Returned')?.closest('li');

            expect(disabledFilter).not.toBeNull();
            expect(disabledFilter?.getAttribute('aria-disabled')).toEqual(
                'true'
            );
        });

        it('should remove all filters when the "Remove all filters" button is clicked', async () => {
            render(<Basic />);

            // First, check we don't have a clear filters option yet
            await screen.findByText('Add filter');
            fireEvent.click(screen.getByText('Add filter'));

            await screen.findByText('Title', { selector: 'li > span' });
            expect(screen.queryByDisplayValue('Remove all filters')).toBeNull();

            // Then we apply a filter
            fireEvent.click(
                screen.getByText('Title', { selector: 'li > span' })
            );
            await screen.findByDisplayValue(
                'Accusantium qui nihil voluptatum quia voluptas maxime ab similique'
            );

            // Then we clear all filters
            fireEvent.click(screen.getByText('Add filter'));
            await screen.findByText('Remove all filters');
            fireEvent.click(screen.getByText('Remove all filters'));

            // We check that the previously applied filter has been removed
            await waitFor(() => {
                expect(
                    screen.queryByDisplayValue(
                        'Accusantium qui nihil voluptatum quia voluptas maxime ab similique'
                    )
                ).toBeNull();
            });
        });

        it('should remove all alwaysOn filters when the "Remove all filters" button is clicked', async () => {
            render(<Basic />);

            // First, check we don't have a clear filters option yet
            await screen.findByText('Add filter');
            fireEvent.click(screen.getByText('Add filter'));

            await screen.findByText('Title', { selector: 'li > span' });
            expect(screen.queryByDisplayValue('Remove all filters')).toBeNull();

            // Then we apply a filter to an alwaysOn filter
            fireEvent.change(screen.getByLabelText('Search'), {
                target: {
                    value:
                        'Accusantium qui nihil voluptatum quia voluptas maxime ab similique',
                },
            });
            await screen.findByDisplayValue(
                'Accusantium qui nihil voluptatum quia voluptas maxime ab similique'
            );

            // Then we clear all filters
            fireEvent.click(screen.getByText('Add filter'));
            await screen.findByText('Remove all filters');
            fireEvent.click(screen.getByText('Remove all filters'));

            // We check that the previously applied filter has been removed
            await waitFor(() => {
                expect(
                    screen.queryByDisplayValue(
                        'Accusantium qui nihil voluptatum quia voluptas maxime ab similique'
                    )
                ).toBeNull();
            });
        });

        it('should not display save query in filter button', async () => {
            const { queryByText } = render(
                <AdminContext theme={theme}>
                    <ListContextProvider
                        value={{
                            ...defaultListContext,
                            filterValues: { title: 'foo' },
                        }}
                    >
                        <FilterButton
                            filters={[
                                <TextInput
                                    source="Returned"
                                    label="Returned"
                                />,
                            ]}
                            disableSaveQuery
                        />
                    </ListContextProvider>
                </AdminContext>
            );
            expect(
                screen.queryByLabelText('ra.action.add_filter')
            ).not.toBeNull();

            fireEvent.click(screen.getByLabelText('ra.action.add_filter'));

            await screen.findByText('Returned');

            expect(queryByText('ra.saved_queries.new_label')).toBeNull();
        });

        it('should close the filter menu on removing all filters', async () => {
            render(<WithAutoCompleteArrayInput />);

            // Open Posts List
            fireEvent.click(await screen.findByText('Posts'));

            await waitFor(() => {
                expect(screen.queryAllByRole('checkbox')).toHaveLength(11);
            });

            fireEvent.click(await screen.findByLabelText('Open'));
            fireEvent.click(await screen.findByText('Sint...'));

            await screen.findByLabelText('Add filter');
            await waitFor(
                () => {
                    expect(screen.getAllByRole('checkbox')).toHaveLength(2);
                },
                { timeout: 10000 }
            );
            fireEvent.click(screen.getByLabelText('Add filter'));
            fireEvent.click(await screen.findByText('Remove all filters'));

            await waitFor(() => {
                expect(screen.getAllByRole('checkbox')).toHaveLength(11);
            });

            fireEvent.click(await screen.findByLabelText('Open'));
            fireEvent.click(await screen.findByText('Sint...'));

            await waitFor(
                () => {
                    expect(screen.getAllByRole('checkbox')).toHaveLength(2);
                },
                { timeout: 4000 }
            );

            expect(screen.queryByText('Save current query...')).toBeNull();
        }, 20000);
    });
});

import * as React from 'react';
import { forwardRef, useCallback } from 'react';
import PropTypes from 'prop-types';
import MenuItem from '@mui/material/MenuItem';
import { FieldTitle, useResourceContext } from 'ra-core';

export const FilterButtonMenuItem = forwardRef<any, FilterButtonMenuItemProps>(
    (props, ref) => {
        const { filter, onShow, autoFocus } = props;
        const resource = useResourceContext(props);
        const handleShow = useCallback(() => {
            onShow({
                source: filter.props.source,
                defaultValue: filter.props.defaultValue,
            });
        }, [filter.props.defaultValue, filter.props.source, onShow]);

        return (
            <MenuItem
                className="new-filter-item"
                data-key={filter.props.source}
                data-default-value={filter.props.defaultValue}
                key={filter.props.source}
                onClick={handleShow}
                autoFocus={autoFocus}
                ref={ref}
                disabled={filter.props.disabled}
            >
                <FieldTitle
                    label={filter.props.label}
                    source={filter.props.source}
                    resource={resource}
                />
            </MenuItem>
        );
    }
);

FilterButtonMenuItem.propTypes = {
    filter: PropTypes.element.isRequired,
    onShow: PropTypes.func.isRequired,
    resource: PropTypes.string,
    autoFocus: PropTypes.bool,
};

export interface FilterButtonMenuItemProps {
    filter: JSX.Element;
    onShow: (params: { source: string; defaultValue: any }) => void;
    resource: string;
    autoFocus?: boolean;
}

import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import expect from 'expect';
import {
    ListContext,
    ListContextProvider,
    minLength,
    ResourceContextProvider,
    testDataProvider,
    ListControllerResult,
} from 'ra-core';
import * as React from 'react';

import { AdminContext } from '../../AdminContext';
import { ReferenceInput, SelectInput, TextInput } from '../../input';
import { Filter } from './Filter';
import {
    Basic,
    WithAutoCompleteArrayInput,
    WithArrayInput,
} from './FilterButton.stories';
import {
    FilterForm,
    getFilterFormValues,
    mergeInitialValuesWithDefaultValues,
} from './FilterForm';

describe('<FilterForm />', () => {
    const defaultListContext = ({
        resource: 'post',
        showFilter: () => {},
        hideFilter: () => {},
        displayedFilters: {},
    } as unknown) as ListControllerResult;

    beforeAll(() => {
        window.scrollTo = jest.fn();
    });

    afterAll(() => {
        jest.clearAllMocks();
    });

    it('should display correctly passed filters', () => {
        const setFilters = jest.fn();
        const filters = [
            <TextInput source="title" label="Title" />,
            <TextInput source="customer.name" label="Name" />,
        ];
        const displayedFilters = {
            title: true,
            'customer.name': true,
        };

        render(
            <AdminContext>
                <ListContextProvider
                    value={{
                        ...defaultListContext,
                        setFilters,
                        displayedFilters,
                    }}
                >
                    <FilterForm filters={filters} />
                </ListContextProvider>
            </AdminContext>
        );
        expect(screen.queryAllByLabelText('Title')).toHaveLength(1);
        expect(screen.queryAllByLabelText('Name')).toHaveLength(1);
    });

    it('should retain key values in the form inputs', () => {
        // As key is not rendered, we just test that the React warning doesn't occur.
        const origError = console.error;
        console.error = message => {
            throw new Error(message);
        };

        const setFilters = jest.fn();
        const filters = [
            <TextInput source="title" label="Title" key="custom-key" />,
            <TextInput source="title" label="Title2" key="another-key" />,
        ];
        const displayedFilters = {
            title: true,
            title2: true,
        };

        expect(() => {
            render(
                <AdminContext>
                    <ListContextProvider
                        value={{
                            ...defaultListContext,
                            setFilters,
                            displayedFilters,
                        }}
                    >
                        <FilterForm filters={filters} />
                    </ListContextProvider>
                </AdminContext>
            );
        }).not.toThrow();
        console.error = origError;
    });

    it('should change the filter when the user updates an input', async () => {
        const filters = [<TextInput source="title" label="Title" />];
        const displayedFilters = {
            title: true,
        };
        const setFilters = jest.fn();

        render(
            <AdminContext>
                <ListContextProvider
                    value={{
                        ...defaultListContext,
                        setFilters,
                        displayedFilters,
                    }}
                >
                    <FilterForm filters={filters} />
                </ListContextProvider>
            </AdminContext>
        );
        fireEvent.change(screen.queryByLabelText('Title') as Element, {
            target: { value: 'foo' },
        });
        await waitFor(() => {
            expect(setFilters).toHaveBeenCalledWith(
                { title: 'foo' },
                { title: true },
                true
            );
        });
    });

    it('should not change the filter when the user updates an input with an invalid value', async () => {
        const filters = [
            <TextInput
                source="title"
                label="Title"
                validate={[minLength(5)]}
            />,
        ];
        const displayedFilters = {
            title: true,
        };
        const setFilters = jest.fn();

        render(
            <AdminContext>
                <ListContextProvider
                    value={{
                        ...defaultListContext,
                        setFilters,
                        displayedFilters,
                    }}
                >
                    <FilterForm filters={filters} />
                </ListContextProvider>
            </AdminContext>
        );
        fireEvent.change(screen.queryByLabelText('Title') as HTMLElement, {
            target: { value: 'foo' },
        });
        await waitFor(() => {
            expect(setFilters).not.toHaveBeenCalled();
        });
    });

    it('should provide ressource context for ReferenceInput filters', async () => {
        const defaultProps: any = {
            context: 'form',
            resource: 'comments',
            setFilters: jest.fn(),
            hideFilter: jest.fn(),
            showFilter: jest.fn(),
            displayedFilters: { post_id: true },
        };
        const dataProvider = testDataProvider({
            // @ts-ignore
            getList: () => Promise.resolve({ data: [], total: 0 }),
        });

        render(
            <AdminContext dataProvider={dataProvider}>
                <ResourceContextProvider value="comments">
                    <ListContext.Provider value={defaultProps}>
                        <Filter>
                            <ReferenceInput source="post_id" reference="posts">
                                <SelectInput optionText="title" />
                            </ReferenceInput>
                        </Filter>
                    </ListContext.Provider>
                </ResourceContextProvider>
            </AdminContext>
        );
        await waitFor(() => {
            expect(
                screen.getByText('resources.comments.fields.post_id')
            ).not.toBeNull();
        });
        const filters = [
            <TextInput
                source="title"
                label="Title"
                validate={[minLength(5)]}
            />,
        ];
        const displayedFilters = {
            title: true,
        };
        const setFilters = jest.fn();

        render(
            <AdminContext>
                <ListContextProvider
                    value={{
                        ...defaultListContext,
                        setFilters,
                        displayedFilters,
                    }}
                >
                    <FilterForm filters={filters} />
                </ListContextProvider>
            </AdminContext>
        );
        fireEvent.change(screen.queryByLabelText('Title') as Element, {
            target: { value: 'foo' },
        });
        await waitFor(() => {
            expect(setFilters).not.toHaveBeenCalled();
        });
    });

    it('should allow to add and clear a filter with a complex object value', async () => {
        render(<Basic />);

        const addFilterButton = await screen.findByText('Add filter');
        fireEvent.click(addFilterButton);

        fireEvent.click(await screen.findByText('Nested'));
        await screen.findByDisplayValue('bar');
        await screen.findByText('1-7 of 7');

        fireEvent.change(screen.getByLabelText('Nested'), {
            target: { value: 'baz' },
        });
        await screen.findByText('1-6 of 6');

        fireEvent.click(await screen.findByTitle('Remove this filter'));
        await screen.findByText('1-10 of 13');
        await waitFor(() => {
            expect(screen.queryByText('Nested')).toBeNull();
        });
        expect(screen.queryByLabelText('Nested')).toBeNull();
    });

    it('should provide a FormGroupContext', async () => {
        render(<WithArrayInput />);

        fireEvent.click(await screen.findByLabelText('Add'));
        fireEvent.change((await screen.findAllByLabelText('Title'))[0], {
            target: { value: 'Sint dignissimos in architecto aut' },
        });
        fireEvent.click(await screen.findByLabelText('Add'));

        await waitFor(() => {
            expect(screen.getAllByText('Title')).toHaveLength(3);
        });
        fireEvent.change((await screen.findAllByLabelText('Title'))[1], {
            target: { value: 'Sed quo et et fugiat modi' },
        });

        await screen.findByText('1-2 of 2');
    });

    describe('mergeInitialValuesWithDefaultValues', () => {
        it('should correctly merge initial values with the default values of the alwaysOn filters', () => {
            const initialValues = {
                title: 'initial title',
            };
            const filters = [
                {
                    props: {
                        source: 'title',
                        alwaysOn: true,
                        defaultValue: 'default title',
                    },
                },
                {
                    props: {
                        source: 'url',
                        alwaysOn: true,
                        defaultValue: 'default url',
                    },
                },
                {
                    props: {
                        source: 'author.name',
                        alwaysOn: true,
                        defaultValue: 'default author',
                    },
                },
                { props: { source: 'notMe', defaultValue: 'default url' } },
                { props: { source: 'notMeEither' } },
            ];

            expect(
                mergeInitialValuesWithDefaultValues(initialValues, filters)
            ).toEqual({
                title: 'initial title',
                url: 'default url',
                author: { name: 'default author' },
            });
        });
    });

    describe('getFilterFormValues', () => {
        it('should correctly get the filter form values from the new filterValues', () => {
            const currentFormValues = {
                classicToClear: 'abc',
                nestedToClear: { nestedValue: 'def' },
                classicUpdated: 'ghi',
                nestedUpdated: { nestedValue: 'jkl' },
                published_at: new Date('2022-01-01T03:00:00.000Z'),
                clearedDateValue: null,
            };
            const newFilterValues = {
                classicUpdated: 'ghi2',
                nestedUpdated: { nestedValue: 'jkl2' },
                published_at: '2022-01-01T03:00:00.000Z',
            };

            expect(
                getFilterFormValues(currentFormValues, newFilterValues)
            ).toEqual({
                classicToClear: '',
                nestedToClear: { nestedValue: '' },
                classicUpdated: 'ghi2',
                nestedUpdated: { nestedValue: 'jkl2' },
                published_at: '2022-01-01T03:00:00.000Z',
                clearedDateValue: '',
            });
        });
    });

    it('should not reapply previous filter form values when clearing nested AutocompleteArrayInput', async () => {
        render(<WithAutoCompleteArrayInput />);

        // Open Posts List
        fireEvent.click(await screen.findByText('Posts'));

        // Set nested filter value to 'bar'
        fireEvent.click(await screen.findByLabelText('Add filter'));
        fireEvent.click(
            await screen.findByRole('menuitem', { name: 'Nested' })
        );
        fireEvent.click(await screen.findByText('bar'));
        fireEvent.blur(await screen.findByLabelText('Nested'));
        await screen.findByText('1-7 of 7');
        expect(screen.queryByRole('button', { name: 'bar' })).not.toBeNull();

        // Navigate to Dashboard
        fireEvent.click(await screen.findByText('Dashboard'));
        // Navigate back to Posts List
        fireEvent.click(await screen.findByText('Posts'));
        // Filter should still be applied
        await screen.findByText('1-7 of 7');
        expect(screen.queryByRole('button', { name: 'bar' })).not.toBeNull();

        // Clear nested filter value
        fireEvent.mouseDown(
            await screen.findByLabelText('Nested', { selector: 'input' })
        );
        fireEvent.keyDown(
            await screen.findByLabelText('Nested', { selector: 'input' }),
            {
                key: 'Backspace',
            }
        );
        fireEvent.blur(
            await screen.findByLabelText('Nested', { selector: 'input' })
        );

        // Wait until filter is cleared
        await screen.findByText('1-10 of 13');
        // Make sure the 'bar' value is not displayed anymore
        expect(screen.queryByRole('button', { name: 'bar' })).toBeNull();
    }, 10000);
});

import * as React from 'react';
import {
    HtmlHTMLAttributes,
    ReactNode,
    useEffect,
    useCallback,
    useContext,
} from 'react';
import PropTypes from 'prop-types';
import { styled } from '@mui/material/styles';
import {
    FormGroupsProvider,
    SourceContextProvider,
    SourceContextValue,
    useListContext,
    useResourceContext,
} from 'ra-core';
import {
    FieldValues,
    FormProvider,
    useForm,
    useFormContext,
} from 'react-hook-form';
import set from 'lodash/set';
import unset from 'lodash/unset';
import get from 'lodash/get';
import cloneDeep from 'lodash/cloneDeep';
import isEqual from 'lodash/isEqual';

import { FilterFormInput } from './FilterFormInput';
import { FilterContext } from '../FilterContext';

export const FilterForm = (props: FilterFormProps) => {
    const { defaultValues, filters: filtersProps, ...rest } = props;

    const { setFilters, displayedFilters, filterValues } = useListContext();
    const filters = useContext(FilterContext) || filtersProps;

    const mergedInitialValuesWithDefaultValues = mergeInitialValuesWithDefaultValues(
        defaultValues || filterValues,
        filters
    );

    const form = useForm({
        defaultValues: mergedInitialValuesWithDefaultValues,
    });
    const { getValues, reset, trigger, watch } = form;

    // Reapply filterValues when the URL changes or a user removes a filter
    useEffect(() => {
        const newValues = getFilterFormValues(getValues(), filterValues);
        const previousValues = getValues();
        if (!isEqual(newValues, previousValues)) {
            reset(newValues);
        }
        // The reference to the filterValues object is not updated when it changes,
        // so we must stringify it to compare it by value and also compare the reference.
        // This makes it work for both input values and filters applied directly through
        // the ListContext.setFilter (e.g. QuickFilter in the simple example)
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [JSON.stringify(filterValues), filterValues, getValues, reset]);

    useEffect(() => {
        const subscription = watch(async (values, { name }) => {
            // We must check whether the form is valid as watch will not check that for us.
            // We can't rely on form state as it might not be synchronized yet
            const isFormValid = await trigger();

            // Check that the name is present to avoid setting filters when watch was
            // triggered by a change on the ListContext values.
            if (name && isFormValid) {
                if (get(values, name) === '') {
                    const newValues = cloneDeep(values);
                    unset(newValues, name);
                    setFilters(newValues, displayedFilters, true);
                } else {
                    setFilters(values, displayedFilters, true);
                }
            }
        });
        return () => subscription.unsubscribe();
    }, [displayedFilters, setFilters, trigger, watch]);

    return (
        <FormProvider {...form}>
            <FormGroupsProvider>
                <FilterFormBase
                    onSubmit={handleFormSubmit}
                    filters={filters}
                    {...rest}
                />
            </FormGroupsProvider>
        </FormProvider>
    );
};

export type FilterFormProps = FilterFormBaseProps & {
    defaultValues?: FieldValues;
};

export const FilterFormBase = (props: FilterFormBaseProps) => {
    const { className, filters, ...rest } = props;
    const resource = useResourceContext(props);
    const form = useFormContext();
    const { displayedFilters = {}, hideFilter } = useListContext();

    useEffect(() => {
        filters.forEach((filter: JSX.Element) => {
            if (filter.props.alwaysOn && filter.props.defaultValue) {
                throw new Error(
                    'Cannot use alwaysOn and defaultValue on a filter input. Please set the filterDefaultValues props on the <List> element instead.'
                );
            }
        });
    }, [filters]);

    const getShownFilters = () => {
        const values = form.getValues();
        return filters.filter((filterElement: JSX.Element) => {
            const filterValue = get(values, filterElement.props.source);
            return (
                filterElement.props.alwaysOn ||
                displayedFilters[filterElement.props.source] ||
                (filterValue !== '' && typeof filterValue !== 'undefined')
            );
        });
    };

    const handleHide = useCallback(
        event => hideFilter(event.currentTarget.dataset.key),
        [hideFilter]
    );

    const sourceContext = React.useMemo<SourceContextValue>(
        () => ({
            getSource: (source: string) => source,
            getLabel: (source: string) =>
                `resources.${resource}.fields.${source}`,
        }),
        [resource]
    );

    return (
        <SourceContextProvider value={sourceContext}>
            <StyledForm
                className={className}
                {...sanitizeRestProps(rest)}
                onSubmit={handleSubmit}
            >
                {getShownFilters().map((filterElement: JSX.Element) => (
                    <FilterFormInput
                        key={filterElement.key || filterElement.props.source}
                        filterElement={filterElement}
                        handleHide={handleHide}
                        resource={resource}
