export const FilterListItem = memo((props: FilterListItemProps) => {
    const {
        label,
        value,
        icon,
        isSelected: getIsSelected = DefaultIsSelected,
        toggleFilter: userToggleFilter = DefaultToggleFilter,
        ...rest
    } = props;
    const { filterValues, setFilters } = useListFilterContext();
    const translate = useTranslate();
    const toggleFilter = useEvent(userToggleFilter);

    // We can't wrap this function with useEvent as it is called in the render phase
    const isSelected = getIsSelected(value, filterValues);

    const handleClick = () => setFilters(toggleFilter(value, filterValues));

    return (
        <StyledListItem
            onClick={handleClick}
            selected={isSelected}
            disablePadding
            {...rest}
        >
            <ListItemButton
                disableGutters
                className={FilterListItemClasses.listItemButton}
            >
                {icon && (
                    <ListItemIcon
                        className={FilterListItemClasses.listItemIcon}
                    >
                        {icon}
                    </ListItemIcon>
                )}
                <ListItemText
                    primary={
                        typeof label === 'string' && !isElement(label)
                            ? translate(label, { _: label })
                            : label
                    }
                    className={FilterListItemClasses.listItemText}
                    data-selected={isSelected ? 'true' : 'false'}
                />
                {isSelected && (
                    <ListItemSecondaryAction
                        onClick={event => {
                            event.stopPropagation();
                            handleClick();
                        }}
                    >
                        <IconButton size="small">
                            <CancelIcon />
                        </IconButton>
                    </ListItemSecondaryAction>
                )}
            </ListItemButton>
        </StyledListItem>
    );
}, arePropsEqual);

const DefaultIsSelected = (value, filters) =>
    matches(pickBy(value, val => typeof val !== 'undefined'))(filters);

const DefaultToggleFilter = (value, filters) => {
    const isSelected = matches(
        pickBy(value, val => typeof val !== 'undefined')
    )(filters);

    if (isSelected) {
        const keysToRemove = Object.keys(value);
        return Object.keys(filters).reduce(
            (acc, key) =>
                keysToRemove.includes(key)
                    ? acc
                    : { ...acc, [key]: filters[key] },
            {}
        );
    }

    return { ...filters, ...value };
};

const PREFIX = 'RaFilterListItem';

export const FilterListItemClasses = {
    listItemButton: `${PREFIX}-listItemButton`,
    listItemText: `${PREFIX}-listItemText`,
    listItemIcon: `${PREFIX}-listItemIcon`,
};

const StyledListItem = styled(ListItem, {
    name: PREFIX,
    overridesResolver: (props, styles) => styles.root,
})({
    [`& .${FilterListItemClasses.listItemButton}`]: {
        paddingRight: '2em',
        paddingLeft: '2em',
    },
    [`& .${FilterListItemClasses.listItemText}`]: {
        margin: 0,
    },
    [`& .${FilterListItemClasses.listItemIcon}`]: {
        minWidth: 0,
        marginRight: '0.5em',
    },
});

export interface FilterListItemProps extends Omit<ListItemProps, 'value'> {
    label: string | ReactElement;
    value: any;
    icon?: ReactElement;
    toggleFilter?: (value: any, filters: any) => any;
    isSelected?: (value: any, filters: any) => boolean;
}

import * as React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';

import { Basic, HiddenLabel } from './FilterLiveSearch.stories';

describe('FilterLiveSearch', () => {
    it('renders an empty text input', () => {
        render(<Basic />);
        expect(
            screen.getByLabelText('ra.action.search').getAttribute('type')
        ).toBe('text');
        expect(
            screen.getByLabelText('ra.action.search').getAttribute('value')
        ).toBe('');
    });
    it('filters the list when typing', () => {
        render(<Basic />);
        expect(screen.queryAllByRole('listitem')).toHaveLength(27);
        fireEvent.change(screen.getByLabelText('ra.action.search'), {
            target: { value: 'st' },
        });
        expect(screen.queryAllByRole('listitem')).toHaveLength(2); // Austria and Estonia
    });
    it('clears the filter when user click on the reset button', () => {
        render(<Basic />);
        fireEvent.change(screen.getByLabelText('ra.action.search'), {
            target: { value: 'st' },
        });
        expect(screen.queryAllByRole('listitem')).toHaveLength(2);
        fireEvent.click(screen.getByLabelText('ra.action.clear_input_value'));
        expect(screen.queryAllByRole('listitem')).toHaveLength(27);
    });
    describe('hiddenLabel', () => {
        it('turns the label into a placeholder', () => {
            render(<HiddenLabel />);
            expect(
                screen
                    .getByPlaceholderText('ra.action.search')
                    .getAttribute('type')
            ).toBe('text');
            expect(screen.queryByLabelText('ra.action.search')).toBeNull();
        });
    });
});

